    var H = canvasH(), out = [];
    for (var y = NOW_Y; y >= BOTTOM_Y; y--) { // year regions: scroll anchors (#y2025) + full-width rules + axis pills
      var t = yearTop(y), b = y > BOTTOM_Y ? yearTop(y - 1) : H;
      out.push('<div class="' + (yearCounts[y] ? 'year ' : '') + 'sp-year" id="y' + y + '" data-year="' + y + '" style="top:' + t + 'px;height:' + (b - t) + 'px">' +
        (y < NOW_Y ? '<span class="sp-ypill">' + y + '</span>' : '') + '</div>');
    }
    out.push(spAxis());
    companies.forEach(function (c) { out.push(spBand(c)); });
    // DOM / tab order = newest end first across both sides
    projects.slice().sort(function (a, b) { return (b._e - a._e) || (b._s - a._s) || (a.co === b.co ? 0 : coById[a.co].side === 'left' ? -1 : 1); })
      .forEach(function (p) { out.push(spProject(p, hit[p.id])); });
